    "schema": "bio-idea.v1",
    "targetId": "poi-bio",
    "targetName": "Wollmatinger Ried",
    "taskDomain": "science_bio",
    "client": {
      "name": "Bodensee-Institut für Feuchtgebietsökologie",
      "kind": "research_institution"
    },
    "situation": "Für das Projekt 'Uferdynamik und Verlandungszonen' benötigen wir eine großräumige Bestandsaufnahme der sichtbaren Vegetationskanten am Übergang zum Wasser. Da die Wasserstände saisonal schwanken, ist eine aktuelle Flugbeobachtung nötig, um die Zonen für die botanischen Kartierungen am Boden festzulegen.",
    "scenarioDetails": [
      "Die Hypothese ist, dass sich durch aktuelle Wasserstandsschwankungen neue Verlandungszonen gebildet haben könnten.",
      "Es wird angenommen, dass bestimmte Vegetationsinseln mittlerweile mit dem Festland verbunden sind."
    ],
    "aerialObservation": {
      "visibleCue": "Muster in der Farbgebung und Textur der Ufervegetation sowie sichtbare Schlickflächen.",
      "usefulObservation": "Unterscheidung zwischen dichten Röhrichtbeständen und offenen Schlammflächen aus der Vogelperspektive.",
      "followup": "Festlegung von Transekten für die detaillierte Bestimmung von Pionierpflanzen am Boden."
    },
    "studyFocus": "Strukturelle Gliederung der Verlandungsbereiche und Identifikation von Fokusarealen für die Sukzessionsforschung.",
    "outputUse": "Die Übersicht dient als Basis für einen Probenahmeplan zur Untersuchung der Nährstoffdynamik in neu entstandenen Flachwasserbereichen.",
    "studyEvidence": {
      "factIds": [],
      "relevance": "Da nur die Kategorie 'nature' ohne Detailbelege vorliegt, dient der Flug primär der ersten räumlichen Orientierung und dem Erkennen grober Landschaftsstrukturen im Ried."
    },
    "person": {
      "name": "Dr. Elena Vogt",
      "role": "Hydrobotanikerin",
      "gender": "female"
    },
    "sceneIntent": {
      "summary": "Erkundungsflug über das Ried zur Vorbereitung bodengebundener Sukzessionsstudien bei aktuellem Wasserstand.",
      "visibleIdeas": [
        "Angeschwemmtes Treibholz und organische Ablagerungen an den flachen Uferlinien",
        "Einige kleinere temporäre Forschungssonden an langen Stangen im Schilfbereich"
      ],
      "densityHint": "sparse",
      "notes": "Der Fokus liegt auf der natürlichen Ufermorphologie; die zusätzlichen Objekte dienen als visuelle Anhaltspunkte für die Feldarbeit.",
      "animalGroups": []
    }
  }
]

