    {
      "schema": "news-idea.v1",
      "targetId": "poi-news",
      "targetName": "Schluchsee-Staumauer",
      "taskDomain": "news_coverage",
      "outlet": "Schwarzwald Echo - Magazin für Kultur & Heimat",
      "headline": "Das Echo der Staumauer: Wenn Beton Musik macht",
      "situation": "Eine Gruppe von Alphornbläsern probt für ein großes Sonnenaufgangskonzert direkt auf der Mauerkrone. Sie nutzen die spezielle Akustik des Tals, um das Zusammenspiel zwischen den Instrumenten auf der Mauer und einer zweiten Gruppe am gegenüberliegenden Ufer zu testen.",
      "angle": "Die Reportage erkundet, wie eine massive technische Barriere wie die Staumauer durch kulturelle Nutzung zu einem verbindenden Resonanzraum für die Region wird.",
      "airValue": "Die Luftperspektive zeigt die langen, charakteristischen Silhouetten der Alphörner auf der schmalen Mauerkrone, eingebettet in die tiefblaue Wasserfläche und die dichten Schwarzwaldtannen.",
      "deliverable": "Ein bebilderter Hintergrundbericht über moderne Heimatpflege und die akustischen Besonderheiten großer Bauwerke.",
      "person": {
        "name": "Lukas Bergmann",
        "role": "Kulturredakteur",
        "gender": "male"
      },
      "sceneIntent": {
        "summary": "Auf der Staumauer und an den Uferrändern haben sich Musiker mit ihren markanten Instrumenten positioniert. Ein kleiner Versorgungsbereich am Ende der Mauer dient als Treffpunkt.",
        "visibleIdeas": [
          "Eine Gruppe von zehn Musikern mit langen Alphörnern, die in regelmäßigem Abstand auf der Mauerkrone stehen.",
          "Ein weißer Festpavillon und zwei Bierzeltgarnituren am östlichen Mauereinstieg als Pausenzone.",
          "Drei PKW und ein Transporter der Musiker auf dem angrenzenden Waldparkplatz.",
          "Eine kleine Gruppe von Wanderern, die auf den Aussichtspunkten oberhalb der Mauer stehen und zuschauen.",
          "Einige aufgestellte Notenständer mit bunten Windschutz-Klammern auf der Mauer."
        ],
        "densityHint": "normal",
        "notes": "Die langen Alphörner sind aus der Luft als markante Linien auf dem grauen Beton der Mauer gut erkennbar und setzen den farblichen Akzent der Szene."
      }
    }
  ]
}

